<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#efeee8">
  <title>We'll be right back — Bakhtech</title>
  <style>
    *{box-sizing:border-box}body{margin:0;background:#efeee8;color:#171715;font-family:system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}main{max-width:1180px;margin:auto;min-height:100svh;display:flex;flex-direction:column;padding:32px 28px}header{font-size:22px;font-weight:800;letter-spacing:-1px}header span{color:#168574}section{flex:1;display:grid;grid-template-columns:1fr 1.08fr;gap:72px;align-items:center;padding:70px 0}.status{font-size:13px;color:#527067;display:flex;gap:10px;align-items:center}.dot{width:8px;height:8px;border-radius:50%;background:#1daf9c;box-shadow:0 0 0 5px #1daf9c18}h1{font-size:clamp(36px,4.5vw,57px);line-height:1.06;letter-spacing:-2.5px;font-weight:650;margin:24px 0}p{color:#686860;line-height:1.8;font-size:15px}.progress{margin:30px 0}.line{height:5px;background:#d8dfd8;border-radius:5px;overflow:hidden;margin:12px 0}.line:before{content:"";display:block;width:35%;height:100%;background:#1daf9c;animation:travel 3s ease-in-out infinite alternate;border-radius:5px}.steps{display:flex;justify-content:space-between;font-size:11px;color:#77786f}.progress strong{font-size:13px;font-weight:600}label{display:block;font-size:14px;font-weight:600;margin-bottom:10px}.fields{display:flex;gap:8px}input{min-width:0;flex:1;padding:13px;border:1px solid #d6d7cf;border-radius:8px;background:#fff;font:inherit;font-size:15px}button{border:0;border-radius:8px;padding:13px 18px;background:#171715;color:white;font:inherit;font-size:14px;font-weight:600;cursor:pointer}button:disabled{opacity:.65;cursor:wait}input:focus-visible,button:focus-visible,a:focus-visible{outline:3px solid #1daf9c;outline-offset:3px}.hint{font-size:12px;margin-top:10px}.message{font-size:14px;color:#176858}.error{color:#a02b2b}.check{display:inline-block;margin-top:24px;color:#171715;font-size:13px;text-underline-offset:5px}.art{border-radius:24px;min-height:480px;display:grid;place-items:center;background:radial-gradient(ellipse at center,#d1e8df 0,transparent 68%),repeating-linear-gradient(30deg,transparent 0 38px,#d1d6c833 39px 40px);overflow:hidden}.art svg{width:100%;max-width:520px}.float{animation:float 5s ease-in-out infinite}.beam{stroke-dasharray:6 8;animation:flow 3s linear infinite}footer{display:flex;justify-content:space-between;gap:16px;font-size:11px;color:#77786f;padding-bottom:8px}@keyframes float{50%{transform:translateY(-12px)}}@keyframes flow{to{stroke-dashoffset:-56}}@keyframes travel{to{transform:translateX(185%)}}@media(max-width:760px){main{padding:24px}section{grid-template-columns:1fr;gap:32px;padding:40px 0}.art{min-height:240px;grid-row:1}.art svg{max-width:300px}h1{letter-spacing:-1.5px}.fields{flex-direction:column}footer{flex-wrap:wrap}}@media(prefers-reduced-motion:reduce){*{animation:none!important}}
  </style>
</head>
<body>
<main>
  <header>Bakhtech<span>.</span></header>
  <section>
    <div>
      <div class="status"><span class="dot" aria-hidden="true"></span>Website maintenance in progress</div>
      <h1>We're making Bakhtech even better.</h1>
      <p>We're updating the website and checking that everything is working as it should. Some features are temporarily unavailable. Thank you for your patience.</p>
      <div class="progress"><strong>Improvements are underway</strong><div class="line" role="progressbar" aria-label="Maintenance in progress; completion time not yet available"></div><div class="steps"><span>Back up</span><span>Update</span><span>Check</span><span>Back online</span></div><p class="hint">We'll be back once the checks are complete.</p></div>
      <form id="notify-form">
        <label for="email">Get an email when we're back</label>
        <div class="fields"><input id="email" name="email" type="email" autocomplete="email" maxlength="254" placeholder="you@example.com" required><button id="notify-button" type="submit">Notify me</button></div>
        <p class="hint">One email about this maintenance. No marketing subscription.</p>
        <p id="notify-message" class="message" role="status" aria-live="polite"></p>
      </form>
      <noscript><p>Please enable JavaScript to request an email notification.</p></noscript>
      <a class="check" href="/">Check if we're back online ↗</a>
    </div>
    <div class="art" aria-hidden="true">
      <svg viewBox="0 0 520 440" fill="none" xmlns="http://www.w3.org/2000/svg">
        <ellipse cx="260" cy="360" rx="178" ry="40" fill="#192e2410"/>
        <path d="M72 302L260 192L448 302L260 412Z" fill="#e6e9df" stroke="#b5beb1"/>
        <path d="M110 280L260 193L410 280L260 367Z" fill="#f6f7f0" stroke="#94a496"/>
        <path class="beam" d="M130 278L260 352L390 278M260 352V205" stroke="#1daf9c" stroke-width="2"/>
        <g class="float">
          <path d="M156 162L260 101L364 162V280L260 341L156 280Z" fill="#e8ede3" stroke="#718778"/>
          <path d="M156 162L260 222L364 162L260 101Z" fill="#fffef6" stroke="#718778"/>
          <path d="M260 222V341L364 280V162Z" fill="#c2d5c7" stroke="#718778"/>
          <path d="M156 201L260 261L364 201M156 240L260 300L364 240" stroke="#718778"/>
          <path d="M177 187L225 215M177 226L225 254M177 265L225 293" stroke="#8ea295" stroke-width="4" stroke-linecap="round"/>
          <path d="M283 230L337 199M283 269L337 238M283 308L337 277" stroke="#1daf9c" stroke-width="4" stroke-linecap="round"/>
          <path d="M213 163L246 182L305 148" stroke="#1daf9c" stroke-width="8" stroke-linecap="round" stroke-linejoin="round"/>
        </g>
        <circle cx="385" cy="111" r="32" fill="#1daf9c"/><path d="M370 111L380 121L400 101" stroke="white" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/>
        <path d="M96 162H119M107 151V174M392 328H408M400 320V336" stroke="#6d9f8f" stroke-width="2"/>
      </svg>
    </div>
  </section>
  <footer><span>Thoughtful improvements. A better experience.</span><span>Bakhtech Solutions</span></footer>
</main>
<script>
  document.getElementById('notify-form').addEventListener('submit', async function(event) {
    event.preventDefault();
    const button = document.getElementById('notify-button');
    const message = document.getElementById('notify-message');
    if (button.disabled) return;
    button.disabled = true; button.textContent = 'Saving…'; message.textContent = ''; message.className = 'message';
    try {
      const response = await fetch('/api/maintenance/notify', {method:'POST', headers:{'Content-Type':'application/json','Accept':'application/json'}, body:JSON.stringify({email:document.getElementById('email').value})});
      if (!response.ok) throw new Error(response.status === 429 ? 'Too many attempts. Please try again in a few minutes.' : 'We could not save your email. Please try again shortly.');
      message.textContent = "You're on the list. We'll email you when the website is back online.";
      button.textContent = 'Saved';
    } catch(error) { message.textContent = error.message; message.className = 'message error'; button.disabled = false; button.textContent = 'Notify me'; }
  });
</script>
</body>
</html>
